from pathlib import Path
import json, shutil

ROOT=Path(__file__).parent/'portfolio'
def put(site,name,text):
 p=ROOT/site/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf-8')
def head(title,desc):
 return f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{desc}"><meta name="theme-color" content="#171917"><title>{title}</title><link rel="icon" href="favicon.svg"><link rel="stylesheet" href="base.css"><link rel="stylesheet" href="style.css"><script src="base.js" defer></script><script src="app.js" defer></script></head>'''
def demo():return '<div class="demo-bar"><span>КОНЦЕПТ ДЛЯ ПОРТФОЛИО</span><span>Вымышленный бренд · заказы и записи не отправляются</span></div>'
def footer(brand,desc,links):
 return f'''<footer class="footer"><div class="wrap footer-inner"><div><a class="wordmark" href="#">{brand}</a><p>{desc}</p></div><nav aria-label="Навигация в подвале">{links}</nav></div><div class="wrap footer-note"><span>© 2026 {brand} · Демо-концепт</span><span>Все товары, цены и услуги — примеры для портфолио.</span></div></footer>'''
def modal():return '<dialog id="modal" aria-labelledby="modal-title"><button class="close" type="button" aria-label="Закрыть окно">×</button><div id="modal-content"></div></dialog><div class="toast" role="status" aria-live="polite"></div>'
