put('impulse','app.js','''const days=['Понедельник','Вторник','Среда','Четверг','Пятница','Суббота','Воскресенье'];let activeDay=0,billing='month';
const classes=[{name:'Силовая',duration:'55 мин',level:'Средний уровень',coach:'Тренер А · демопрофиль'},{name:'Мобильность',duration:'45 мин',level:'Любой уровень',coach:'Тренер Б · демопрофиль'},{name:'Функциональная',duration:'50 мин',level:'Любой уровень',coach:'Тренер В · демопрофиль'},{name:'Растяжка',duration:'45 мин',level:'Начальный уровень',coach:'Тренер Б · демопрофиль'}];
function schedule(){const times=activeDay>4?['09:00','11:00','13:00']:['07:30','12:00','18:30','20:00'];$('#schedule-list').innerHTML=times.map((time,i)=>{const c=classes[(activeDay+i)%classes.length];return `<div class="schedule-row"><time>${time}</time><div><h3>${c.name}</h3><p>${c.duration} · ${c.level}</p></div><span>${c.coach}</span><button data-session="${c.name}" data-time="${time}">Записаться ↗</button></div>`}).join('');$$('[data-session]').forEach(b=>b.onclick=()=>trial(b.dataset.session,days[activeDay]+' · '+b.dataset.time))}
$$('[data-day]').forEach(b=>b.onclick=()=>{activeDay=Number(b.dataset.day);$$('[data-day]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));schedule()});schedule();
const plans=[{name:'START',price:12900,desc:'Для первого шага',features:['8 групповых занятий','Знакомство с направлениями','Доступ по расписанию']},{name:'FLOW',price:19900,desc:'Для собственного ритма',features:['Безлимитные групповые занятия','Тренажёрный зал','Все направления клуба']},{name:'POWER',price:34900,desc:'Для персонального подхода',features:['Всё из FLOW','4 персональные тренировки','Индивидуальная программа']}];
function renderPlans(){$('#plans-grid').innerHTML=plans.map((p,i)=>`<article class="plan ${i===1?'featured':''}"><h3>${p.name}</h3>${i===1?'<span class="plan-badge">НАШ ВЫБОР</span>':''}<p>${p.desc}</p><div class="plan-price"><strong>${money(billing==='month'?p.price:Math.round(p.price*.8))}</strong><span>${billing==='month'?'за месяц':'в месяц при оплате '+money(Math.round(p.price*.8)*12)+' за год'}</span></div><ul>${p.features.map(x=>'<li>'+x+'</li>').join('')}</ul><button class="button full" data-plan="${p.name}">Выбрать ${p.name} ↗</button></article>`).join('');$$('[data-plan]').forEach(b=>b.onclick=()=>trial('Абонемент '+b.dataset.plan,billing==='month'?'На месяц':'На год'))}
$$('[data-billing]').forEach(b=>b.onclick=()=>{billing=b.dataset.billing;$$('[data-billing]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderPlans()});renderPlans();
function trial(choice='Знакомство с клубом',when='Выберем вместе'){openModal(`<p class="eyebrow">IMPULSE / ПЕРВЫЙ ШАГ</p><h2 id="modal-title">Движение начинается здесь.</h2><p>Попробуйте запись. Это демо, заявка никуда не отправится.</p><div class="success-detail"><strong>${esc(choice)}</strong><br>${esc(when)}</div><form id="trial-form"><label class="field">Как к вам обращаться<input name="visitor" maxlength="50" placeholder="Например, Алекс" required autocomplete="off"></label><label class="field">Опыт тренировок<select name="experience"><option>Только начинаю</option><option>Возвращаюсь после перерыва</option><option>Тренируюсь регулярно</option></select></label><button class="button full">Сформировать демозапись ↗</button></form><p class="demo-note">Свободные места и персональные программы в этой версии не рассчитываются.</p>`);$('#trial-form').onsubmit=e=>{e.preventDefault();const f=e.target;if(!f.reportValidity())return;success('Первый шаг сделан.',`${esc(f.visitor.value)}<br>${esc(choice)} · ${esc(when)}<br>${esc(f.experience.value)}<br><br>Это демонстрация. Запись не отправлена.`)}}
$$('[data-trial]').forEach(b=>b.onclick=()=>trial(b.dataset.trial||undefined));''')

